widget.solution:
from math import erf, sqrt

def Phi(x):
    return 0.5 * (1 + erf(x / sqrt(2)))

def power(delta, sigma, n, z_alpha=1.645):
    """Power of a one-sided z test of mean 0 against mean delta."""
    shift = delta * sqrt(n) / sigma
    return Phi(shift - z_alpha)

for n in (25, 100, 155, 400):
    print(n, round(power(0.2, 1, n), 3))
